/* Practice MCQ bank — expansion set, weighted toward heavy blueprint areas.
   Appends to window.CPA_QUESTIONS (load after questions.js). Original study aids, not AICPA items.
   Indexed/inflation-adjusted dollar amounts avoided; stable statutory figures retained. */
window.CPA_QUESTIONS = (window.CPA_QUESTIONS || []).concat([

/* ============================== FAR (Areas I–III) ============================== */
{ id:"FARQ21", section:"FAR", area:"II", topic:"Inventory methods",
  stem:"In a period of consistently rising purchase prices, which inventory method reports the LOWEST ending inventory and the HIGHEST cost of goods sold?",
  choices:["FIFO","LIFO","Weighted average","Specific identification"], answer:1,
  explanation:"LIFO charges the newest (most expensive) costs to COGS, leaving the oldest (cheapest) layers in ending inventory — lowest inventory, highest COGS, lowest pre-tax income in inflation." },
{ id:"FARQ22", section:"FAR", area:"II", topic:"PP&E capitalization",
  stem:"A company buys land with an old building it immediately razes to construct a new plant. The demolition cost (net of salvage proceeds) is:",
  choices:["Expensed as incurred","Capitalized as part of the LAND","Capitalized as part of the new building","Recorded as a loss on disposal"], answer:1,
  explanation:"Costs to prepare land for its intended use — including razing an existing structure, net of salvage — attach to the land. Excavation for the new building's foundation attaches to the building." },
{ id:"FARQ23", section:"FAR", area:"II", topic:"Equity method",
  stem:"An investor owns 30% of an investee and has significant influence. The investee reports $100,000 net income and pays $20,000 of dividends. The investor's income from the investment is:",
  choices:["$6,000","$20,000","$30,000","$36,000"], answer:2,
  explanation:"Equity method: income = 30% × $100,000 = $30,000. Dividends ($6,000 share) are NOT income — they reduce the investment carrying amount." },
{ id:"FARQ24", section:"FAR", area:"II", topic:"Debt securities",
  stem:"Unrealized holding gains on available-for-sale DEBT securities are reported in:",
  choices:["Net income","Other comprehensive income","Retained earnings directly","A valuation allowance in liabilities"], answer:1,
  explanation:"AFS debt: fair value through OCI (recycled to income on sale). Trading debt: through net income. Held-to-maturity: amortized cost (no FV remeasurement). Note: EQUITY securities generally go through net income." },
{ id:"FARQ25", section:"FAR", area:"II", topic:"Intangibles",
  stem:"A patent has a remaining legal life of 10 years, but the company expects it to generate cash flows for only 6 years. Amortize over:",
  choices:["10 years","6 years","15 years","No amortization — test for impairment only"], answer:1,
  explanation:"Finite-lived intangibles amortize over the SHORTER of legal life or useful (economic) life. Only indefinite-lived intangibles (and goodwill) skip amortization for impairment-only testing." },
{ id:"FARQ26", section:"FAR", area:"II", topic:"Compensated absences",
  stem:"An employer must ACCRUE a liability for compensated absences (e.g., vacation) when the obligation relates to services already rendered, the benefits vest or accumulate, payment is probable, and:",
  choices:["The amount is approved by the board","The amount can be reasonably estimated","Employees have requested the time off","The benefits are nontransferable"], answer:1,
  explanation:"All four criteria: services rendered, vest/accumulate, probable, and reasonably estimable. Miss the estimate criterion → disclose instead of accrue." },
{ id:"FARQ27", section:"FAR", area:"I", topic:"EPS",
  stem:"Net income is $500,000; preferred dividends declared are $50,000; weighted-average common shares outstanding are 100,000. Basic EPS is:",
  choices:["$5.00","$4.50","$5.50","$4.00"], answer:1,
  explanation:"Basic EPS = (NI − preferred dividends) / WACSO = ($500,000 − $50,000) / 100,000 = $4.50." },
{ id:"FARQ28", section:"FAR", area:"I", topic:"Consolidation policy",
  stem:"A parent owns 65% of a subsidiary's voting stock. The parent should:",
  choices:["Use the equity method in consolidated statements","Consolidate the subsidiary and report a 35% noncontrolling interest in equity","Report the investment at fair value through OCI","Proportionately consolidate 65% of each account"], answer:1,
  explanation:"Control (generally >50% voting) requires FULL consolidation — 100% of the sub's accounts — with NCI presented in consolidated equity for the 35% not owned." },
{ id:"FARQ29", section:"FAR", area:"I", topic:"NFP restrictions",
  stem:"An NFP spends a donor-restricted gift on the stipulated program. On the statement of activities this is reported as:",
  choices:["Revenue without donor restrictions","Net assets released from restrictions — a reclassification from 'with' to 'without' donor restrictions","A reduction of contribution revenue","An expense of net assets with donor restrictions"], answer:1,
  explanation:"Satisfying a purpose (or time) restriction triggers a reclassification: 'net assets released from restrictions.' Expenses are then reported in the without-donor-restrictions column." },
{ id:"FARQ30", section:"FAR", area:"I", topic:"Fund identification",
  stem:"A city operates a municipal swimming pool intended to be self-supporting through user fees charged to the general public. The pool is accounted for in:",
  choices:["The general fund","A special revenue fund","An enterprise fund","A custodial fund"], answer:2,
  explanation:"Business-type activities financed primarily by user charges to external customers → ENTERPRISE fund (proprietary, full accrual). Internal service funds serve other departments, not the public." },
{ id:"FARQ31", section:"FAR", area:"I", topic:"Cash flow classification",
  stem:"Under US GAAP, which cash outflow is classified as a FINANCING activity?",
  choices:["Interest paid on bonds","Dividends paid to shareholders","Purchase of equipment","Payment to suppliers"], answer:1,
  explanation:"Dividends paid = financing. Interest paid = operating (US GAAP). Equipment = investing. Suppliers = operating. (Debt PRINCIPAL repayment is also financing.)" },
{ id:"FARQ32", section:"FAR", area:"III", topic:"Principal vs agent",
  stem:"An online marketplace facilitates sales between buyers and third-party sellers, never controls the goods, and earns a 10% fee. It should recognize revenue equal to:",
  choices:["The gross transaction price","Its 10% fee (net)","Gross price less estimated returns","Nothing until the seller is paid"], answer:1,
  explanation:"An AGENT (doesn't control the good before transfer) recognizes the net fee. A principal (controls the good, bears inventory/pricing risk) recognizes gross revenue and COGS." },
{ id:"FARQ33", section:"FAR", area:"III", topic:"Contingencies",
  stem:"A company faces a lawsuit where an unfavorable outcome is REASONABLY POSSIBLE and the loss can be estimated. The company should:",
  choices:["Accrue the estimated loss","Disclose the nature and estimate, but not accrue","Neither accrue nor disclose","Accrue the minimum of the range"], answer:1,
  explanation:"Probable + estimable → accrue. REASONABLY POSSIBLE → disclose only. Remote → generally nothing. (If probable with only a range, accrue the best estimate, or the minimum if no amount is better.)" },
{ id:"FARQ34", section:"FAR", area:"III", topic:"Business combinations",
  stem:"Direct acquisition costs (legal and finder's fees) in a business combination are:",
  choices:["Added to goodwill","Capitalized to the assets acquired","Expensed as incurred","Charged against APIC"], answer:2,
  explanation:"Acquisition-related costs are EXPENSED under the acquisition method. (Exception: costs of issuing stock reduce APIC; debt issue costs follow debt accounting.)" },
{ id:"FARQ35", section:"FAR", area:"III", topic:"Foreign currency transactions",
  stem:"A US company has a receivable denominated in euros. Before settlement, the euro strengthens against the dollar. The company reports:",
  choices:["A transaction gain in net income","A translation adjustment in OCI","No effect until settlement","A deferred credit"], answer:0,
  explanation:"Foreign-currency TRANSACTIONS are remeasured at each balance sheet date with gains/losses in NET INCOME. (TRANSLATION of a foreign subsidiary's statements goes to OCI/CTA.)" },
{ id:"FARQ36", section:"FAR", area:"III", topic:"Internal-use software",
  stem:"For internal-use software, costs incurred during the APPLICATION DEVELOPMENT stage (coding, installation, testing) are:",
  choices:["Expensed as incurred","Capitalized","Capitalized only if the software will be sold","Charged to R&D"], answer:1,
  explanation:"Internal-use software: expense the preliminary-project and post-implementation stages; CAPITALIZE application development. (Software FOR SALE capitalizes only after technological feasibility.)" },

/* ============================== AUD (Areas I–IV) ============================== */
{ id:"AUDQ21", section:"AUD", area:"II", topic:"Walkthroughs",
  stem:"The primary purpose of a walkthrough is to:",
  choices:["Test the operating effectiveness of controls over the period","Confirm the auditor's understanding of the process and whether controls have been implemented","Substantiate the year-end account balance","Document management's representations"], answer:1,
  explanation:"Tracing a transaction from origin to the records confirms the auditor's understanding of design and implementation. Operating effectiveness requires tests of controls over the period." },
{ id:"AUDQ22", section:"AUD", area:"II", topic:"Significant risks",
  stem:"For an identified SIGNIFICANT risk, the auditor:",
  choices:["May respond with substantive analytical procedures alone","Must obtain an understanding of relevant controls and perform substantive procedures specifically responsive to that risk","May rely entirely on prior-year evidence of control effectiveness","Should raise overall materiality"], answer:1,
  explanation:"Significant risks require understanding the related controls and specifically responsive substantive procedures — substantive analytics ALONE are not sufficient, and prior-period control evidence can't be relied on without retesting." },
{ id:"AUDQ23", section:"AUD", area:"II", topic:"Related parties",
  stem:"The auditor's primary concern with related-party transactions is:",
  choices:["That they are eliminated from the financial statements","Whether they were properly authorized, accounted for, and DISCLOSED, given they may not be at arm's length","That they always indicate fraud","That they are recorded at fair value"], answer:1,
  explanation:"Related-party transactions are legitimate but may lack arm's-length economics — the focus is identification, business purpose, proper accounting, and disclosure (and fraud alertness, not presumption)." },
{ id:"AUDQ24", section:"AUD", area:"II", topic:"Inherent risk",
  stem:"Which factor MOST increases inherent risk at the assertion level?",
  choices:["Routine, high-volume processing of homogeneous transactions","Account balances based on complex management estimates and judgment","Strong segregation of duties","A stable regulatory environment"], answer:1,
  explanation:"Complexity, estimation uncertainty, and judgment raise inherent risk (susceptibility before controls). Routine processing and strong controls cut the other way — segregation affects CONTROL risk." },
{ id:"AUDQ25", section:"AUD", area:"III", topic:"Data reliability",
  stem:"Before using client-produced data in audit data analytics, the auditor should:",
  choices:["Assume reliability if controls were tested last year","Test the completeness and accuracy of the underlying data","Use it only for immaterial accounts","Have management certify the data in the rep letter"], answer:1,
  explanation:"Evidence is only as good as its inputs: validate completeness and accuracy (e.g., reconcile to the GL, test extraction parameters) before relying on analytics built on client data." },
{ id:"AUDQ26", section:"AUD", area:"III", topic:"Misstatement projection",
  stem:"An auditor samples $50,000 of a $500,000 population and finds $2,000 of overstatement. Using ratio projection, the projected misstatement for the population is:",
  choices:["$2,000","$10,000","$20,000","$200,000"], answer:2,
  explanation:"$2,000 ÷ $50,000 = 4% misstatement rate × $500,000 population = $20,000 projected. Compare (plus sampling-risk allowance) to tolerable misstatement." },
{ id:"AUDQ27", section:"AUD", area:"III", topic:"Litigation",
  stem:"The PRIMARY procedure for corroborating management's assertions about litigation, claims, and assessments is:",
  choices:["Reviewing the client's litigation accrual workpapers","A letter of inquiry to the client's external legal counsel","Confirming with the opposing party's counsel","Reading board minutes only"], answer:1,
  explanation:"The legal letter (attorney letter of inquiry, sent by management, returned directly to the auditor) is the primary corroboration; minutes, invoices, and accruals support it." },
{ id:"AUDQ28", section:"AUD", area:"III", topic:"Going concern",
  stem:"When substantial doubt exists, the auditor evaluates management's mitigation plans. Which plan element matters MOST?",
  choices:["Whether the plans are described eloquently","Whether the plans are FEASIBLE and likely to be effectively implemented within one year of statement issuance","Whether the board approved the plans unanimously","Whether prior-year plans existed"], answer:1,
  explanation:"The test is feasibility and probable effectiveness within the look-forward period (one year from issuance/availability) — e.g., realistic asset disposals, committed financing, cost reductions, equity raises." },
{ id:"AUDQ29", section:"AUD", area:"III", topic:"Inventory observation",
  stem:"Observing the client's physical inventory count primarily provides evidence about:",
  choices:["Rights and obligations","Existence of the inventory","Net realizable value","Completeness of accounts payable"], answer:1,
  explanation:"Observation verifies the inventory EXISTS. Rights need vendor/consignment evidence; valuation needs cost/NRV testing; floor-to-sheet vs. sheet-to-floor direction tests completeness vs. existence." },
{ id:"AUDQ30", section:"AUD", area:"I", topic:"Contingent fees",
  stem:"Under the AICPA Code, a member may charge a contingent fee for:",
  choices:["An audit of financial statements","A review of financial statements","Representing a client in an IRS examination of its return","Preparing an original tax return"], answer:2,
  explanation:"Contingent fees are prohibited for audits, reviews, certain compilations, and original/amended return preparation — but PERMITTED for representing a client in an IRS examination or judicial proceeding." },
{ id:"AUDQ31", section:"AUD", area:"I", topic:"Confidentiality",
  stem:"Without the client's specific consent, a CPA may disclose confidential client information:",
  choices:["To a prospective purchaser of the CPA's practice","In response to a validly issued subpoena or as part of an approved peer review","To the client's competitors for benchmarking","To a successor auditor who requests it"], answer:1,
  explanation:"Exceptions to consent: valid subpoena/summons, peer/quality review, ethics investigations, and complying with standards. Successor auditors and practice buyers need client permission." },
{ id:"AUDQ32", section:"AUD", area:"I", topic:"Quality management",
  stem:"Under the quality management standards, a firm's system of quality management is designed using:",
  choices:["A one-size-fits-all checklist issued by the AICPA","A risk-based approach — setting quality objectives, identifying quality risks, and designing responses","Only post-issuance file inspections","Peer review results from other firms"], answer:1,
  explanation:"The QM standards require a tailored, RISK-BASED system: objectives → quality risks → responses, plus governance/leadership accountability, monitoring, and remediation (and EQRs where required)." },
{ id:"AUDQ33", section:"AUD", area:"IV", topic:"Predecessor auditors",
  stem:"Prior-year statements were audited by a predecessor whose report is NOT re-presented. The successor's report should:",
  choices:["Ignore the prior year entirely","Include an other-matter paragraph stating the predecessor audited the prior period, the opinion type, and the report date","Re-express the predecessor's opinion as the successor's own","Disclaim on the prior year"], answer:1,
  explanation:"An other-matter paragraph communicates: prior period audited by predecessor, the opinion expressed (and reasons for modification, if any), and the date of that report." },
{ id:"AUDQ34", section:"AUD", area:"IV", topic:"Special-purpose frameworks",
  stem:"An audit report on cash-basis financial statements must include:",
  choices:["An adverse opinion, since cash basis departs from GAAP","An emphasis-of-matter paragraph alerting readers that the statements use a special-purpose framework","A disclaimer of opinion","No reference to the framework"], answer:1,
  explanation:"Special-purpose-framework reports require an EOM alerting users to the framework (and, where applicable, restricted use). Cash/tax/regulatory bases are acceptable frameworks — not GAAP departures." },
{ id:"AUDQ35", section:"AUD", area:"IV", topic:"Review reports",
  stem:"The conclusion paragraph of a SSARS review report states that the accountant is:",
  choices:["Expressing an opinion that the statements are fairly presented","Not aware of any material modifications that should be made for the statements to conform with the framework","Providing absolute assurance on the statements","Disclaiming any responsibility for the statements"], answer:1,
  explanation:"Limited (negative) assurance wording: 'not aware of any material modifications…' — distinctly weaker than an audit opinion, stronger than a compilation's no-assurance." },
{ id:"AUDQ36", section:"AUD", area:"II", topic:"Automated controls",
  stem:"A key advantage of automated controls over manual controls is:",
  choices:["They eliminate the need for ITGCs","Consistent application to every transaction processed","They cannot be overridden by management","Lower inherent risk in estimates"], answer:1,
  explanation:"Automation applies the control identically every time — but only if ITGCs (especially change management and access) keep the program reliable. Systematic errors replicate consistently too." },

/* ============================== REG (Areas I–V) ============================== */
{ id:"REGQ21", section:"REG", area:"IV", topic:"Capital losses",
  stem:"An individual has a $10,000 net capital loss this year. The maximum deductible against ordinary income this year is:",
  choices:["$10,000","$3,000, with indefinite carryforward of the rest","$5,000","$0 — capital losses offset only capital gains"], answer:1,
  explanation:"Individuals deduct up to $3,000 of net capital loss against ordinary income per year ($1,500 MFS); the excess carries forward indefinitely, retaining character. (Corporations: carryback 3/forward 5, gains only.)" },
{ id:"REGQ22", section:"REG", area:"IV", topic:"Gross income",
  stem:"Which item is INCLUDED in an individual's gross income?",
  choices:["Municipal bond interest","Life insurance proceeds received by reason of death","Unemployment compensation","A gift of cash from a parent"], answer:2,
  explanation:"Unemployment compensation is fully taxable. Muni interest, death benefits, and gifts are excluded (the DONOR may face gift tax; the recipient excludes)." },
{ id:"REGQ23", section:"REG", area:"IV", topic:"Alimony",
  stem:"Under a divorce agreement executed after December 31, 2018, alimony payments are:",
  choices:["Deductible by the payor and income to the recipient","Neither deductible by the payor nor income to the recipient","Deductible by the payor only","Income to the recipient only"], answer:1,
  explanation:"Post-2018 agreements: no deduction, no income (TCJA). Pre-2019 agreements keep the old deductible/includible regime unless modified to adopt the new rule." },
{ id:"REGQ24", section:"REG", area:"IV", topic:"QBI deduction",
  stem:"The qualified business income (QBI) deduction is generally:",
  choices:["An above-the-line deduction reducing AGI","20% of qualified pass-through business income, taken AFTER AGI (below the line), subject to limitations","Available for C corporation dividends","A refundable credit"], answer:1,
  explanation:"§199A: up to 20% of QBI from sole proprietorships and pass-throughs, below the line (doesn't reduce AGI or SE tax), with wage/UBIA and specified-service limits at higher incomes. Not for C corps." },
{ id:"REGQ25", section:"REG", area:"IV", topic:"Early IRA distributions",
  stem:"A 45-year-old withdraws from a traditional IRA with no exception applying. The withdrawal is subject to:",
  choices:["Income tax only","A 10% additional tax (penalty) plus ordinary income tax","The 10% penalty only","No tax if redeposited within 5 years"], answer:1,
  explanation:"Pre-59½ distributions: ordinary income PLUS the 10% additional tax, unless an exception applies (death, disability, first home, higher education, substantially equal periodic payments, etc.). Rollover window is 60 days." },
{ id:"REGQ26", section:"REG", area:"V", topic:"Dividends-received deduction",
  stem:"A C corporation owns 25% of another domestic corporation's stock. Its dividends-received deduction percentage is:",
  choices:["50%","65%","80%","100%"], answer:1,
  explanation:"DRD tiers: <20% ownership → 50%; 20% to <80% → 65%; ≥80% (affiliated) → 100%. Subject to taxable-income limits." },
{ id:"REGQ27", section:"REG", area:"V", topic:"Corporate charitable limit",
  stem:"A C corporation's charitable contribution deduction is generally limited to:",
  choices:["50% of AGI","10% of taxable income (computed before certain deductions), with a 5-year carryforward of the excess","30% of taxable income","No limit if paid in cash"], answer:1,
  explanation:"Corporations: 10% of taxable income (before the charitable deduction, DRD, and certain other items); excess carries forward 5 years. AGI-based limits apply to individuals." },
{ id:"REGQ28", section:"REG", area:"V", topic:"§351 incorporation",
  stem:"Transferors contribute property to a new corporation solely for stock and, as a group, own 85% of the voting stock immediately after. The transferors recognize:",
  choices:["Gain equal to the built-in appreciation","No gain or loss under §351","Ordinary income equal to the stock's value","Gain only to the extent of liabilities assumed in all cases"], answer:1,
  explanation:"§351: no gain/loss when property is transferred solely for stock and the transferor group has CONTROL (≥80% voting and each class) immediately after. Boot (cash, excess liabilities) triggers gain." },
{ id:"REGQ29", section:"REG", area:"V", topic:"Partnership formation",
  stem:"A partner contributes appreciated property (basis $40,000, FMV $100,000) to a partnership for an interest. The partner recognizes ____ and takes an outside basis of ____.",
  choices:["$60,000 gain; $100,000","No gain (§721); $40,000","No gain; $100,000","$60,000 gain; $40,000"], answer:1,
  explanation:"§721: no gain/loss on contribution. Outside basis = carryover basis of property contributed ($40,000); the partnership takes the same $40,000 inside basis (§723). Built-in gain is tracked under §704(c)." },
{ id:"REGQ30", section:"REG", area:"V", topic:"Guaranteed payments",
  stem:"Guaranteed payments to a partner for services are:",
  choices:["Tax-free returns of capital","Ordinary (and self-employment) income to the partner and deductible by the partnership","Capital gain to the partner","Dividends"], answer:1,
  explanation:"Guaranteed payments (determined without regard to partnership income) are ordinary income to the partner, subject to SE tax, and deducted by the partnership in computing ordinary income." },
{ id:"REGQ31", section:"REG", area:"V", topic:"S election termination",
  stem:"Which event TERMINATES an S election?",
  choices:["Having 80 shareholders","Issuing nonvoting common stock with identical distribution rights","A partnership becoming a shareholder","Earning passive income one year with no E&P"], answer:2,
  explanation:"Ineligible shareholders (partnerships, corporations, nonresident aliens) terminate the election immediately. ≤100 shareholders is fine; voting differences don't create a second class; the passive-income kill rule needs >25% for 3 consecutive years WITH C-corp E&P." },
{ id:"REGQ32", section:"REG", area:"III", topic:"MACRS conventions",
  stem:"The mid-quarter convention applies to personal property when:",
  choices:["Any asset is placed in service in December","More than 40% of the year's personalty (by basis) is placed in service in the fourth quarter","The taxpayer elects out of bonus depreciation","Real property is acquired mid-year"], answer:1,
  explanation:"Default convention for personalty is half-year; >40% placed in service in Q4 forces mid-quarter for ALL personalty that year. Real property always uses mid-month." },
{ id:"REGQ33", section:"REG", area:"I", topic:"Tax practitioner privilege",
  stem:"The federally authorized tax practitioner privilege (§7525) protects:",
  choices:["All communications with any tax preparer","Tax ADVICE communications in noncriminal tax matters before the IRS or federal courts brought by/against the US","Tax return preparation workpapers","Communications about tax shelters in all cases"], answer:1,
  explanation:"§7525 extends attorney-client-style privilege to FATPs but only for tax advice, only in NONCRIMINAL proceedings, and it doesn't cover return preparation or written corporate tax-shelter promotion." },
{ id:"REGQ34", section:"REG", area:"II", topic:"FCPA",
  stem:"The Foreign Corrupt Practices Act prohibits:",
  choices:["All payments to any foreign person","Corrupt payments to foreign officials to obtain or retain business, and requires issuers to keep accurate books and records","Doing business in sanctioned countries","Hiring foreign nationals"], answer:1,
  explanation:"FCPA = anti-bribery provision (corrupt payments to foreign officials) + accounting provisions for issuers (books/records and internal controls). Small 'facilitating payments' for routine acts have a narrow exception." },
{ id:"REGQ35", section:"REG", area:"II", topic:"Worker classification",
  stem:"The factor that MOST strongly indicates employee (rather than independent-contractor) status is:",
  choices:["The worker provides services to multiple clients","The business controls HOW, when, and where the work is performed","The worker supplies their own tools","Payment by the project"], answer:1,
  explanation:"Behavioral control — the right to direct how work is done — is the core employee indicator. Multiple clients, own tools, project pricing, and profit/loss opportunity point toward contractor status." },
{ id:"REGQ36", section:"REG", area:"II", topic:"Bankruptcy discharge",
  stem:"Which debt is generally DISCHARGEABLE in a Chapter 7 bankruptcy?",
  choices:["Domestic support obligations","Credit card balances not involving fraud","Most student loans (absent undue hardship)","Income taxes assessed within the prior year"], answer:1,
  explanation:"Ordinary unsecured consumer debt (no fraud) is dischargeable. Nondischargeable: support obligations, recent taxes, student loans (absent undue hardship), debts from fraud/willful injury, and fines." },

/* ============================== BAR (Areas I–III) ============================== */
{ id:"BARQ19", section:"BAR", area:"I", topic:"ROA",
  stem:"Net income is $120,000 and average total assets are $1,500,000. Return on assets is:",
  choices:["12.5%","8%","6.7%","15%"], answer:1,
  explanation:"ROA = NI / average total assets = 120,000 / 1,500,000 = 8%. (Some texts add back after-tax interest for an unlevered version — use the basic formula unless told otherwise.)" },
{ id:"BARQ20", section:"BAR", area:"I", topic:"DSO",
  stem:"Net credit sales are $730,000 and average accounts receivable is $60,000. Days sales outstanding is approximately:",
  choices:["12 days","30 days","60 days","83 days"], answer:1,
  explanation:"A/R turnover = 730,000 / 60,000 ≈ 12.17×. DSO = 365 / 12.17 ≈ 30 days." },
{ id:"BARQ21", section:"BAR", area:"I", topic:"Cash conversion cycle",
  stem:"Days inventory outstanding 45, days sales outstanding 30, days payables outstanding 25. The cash conversion cycle is:",
  choices:["100 days","50 days","40 days","10 days"], answer:1,
  explanation:"CCC = DIO + DSO − DPO = 45 + 30 − 25 = 50 days of financing need between paying suppliers and collecting from customers." },
{ id:"BARQ22", section:"BAR", area:"I", topic:"Flexible budgets",
  stem:"A flexible budget is prepared using:",
  choices:["Budgeted costs at the original (static) planned volume","The budgeted cost formulas applied to the ACTUAL activity level achieved","Actual costs at actual volume","Prior-year actuals adjusted for inflation"], answer:1,
  explanation:"Flexing the budget to actual volume isolates price/efficiency variances from the volume effect. Static-vs-flexible difference = volume variance; flexible-vs-actual = spending/efficiency variances." },
{ id:"BARQ23", section:"BAR", area:"I", topic:"Regression",
  stem:"A cost regression against machine hours has an R² (coefficient of determination) of 0.81. This means:",
  choices:["The variable cost rate is $0.81 per hour","81% of the variation in cost is explained by machine hours","The correlation is too low to use","Fixed costs are 81% of total"], answer:1,
  explanation:"R² measures explanatory power: 81% of the cost variation is associated with the driver. The slope (b) is the variable rate; the intercept (a) approximates fixed cost." },
{ id:"BARQ24", section:"BAR", area:"I", topic:"Data quality",
  stem:"An analyst discovers that 5% of sales invoices never made it into the analytics dataset. This is a failure of which data-quality dimension?",
  choices:["Accuracy","Completeness","Timeliness","Consistency"], answer:1,
  explanation:"Missing records = COMPLETENESS. Wrong values = accuracy; stale data = timeliness; conflicting values across systems = consistency. Always reconcile datasets to the system of record." },
{ id:"BARQ25", section:"BAR", area:"I", topic:"Sensitivity analysis",
  stem:"Management wants to know which single assumption most affects a project's NPV. The appropriate technique is:",
  choices:["Scenario analysis","Sensitivity analysis — flexing one input at a time","Monte Carlo only","Payback analysis"], answer:1,
  explanation:"Sensitivity analysis varies one input at a time to rank assumption criticality. Scenario analysis moves coherent SETS of inputs; simulation randomizes many inputs simultaneously." },
{ id:"BARQ26", section:"BAR", area:"I", topic:"Benchmarking",
  stem:"When benchmarking ratios against an industry peer, the most important caveat is:",
  choices:["Peers are always larger","Differences in accounting methods (e.g., LIFO vs FIFO, leasing) can distort comparability","Industry data is never available","Ratios only work for public companies"], answer:1,
  explanation:"Method differences (inventory costing, depreciation lives, lease structures, fiscal year-ends) can make identical economics look different. Normalize before concluding." },
{ id:"BARQ27", section:"BAR", area:"II", topic:"Percentage of completion",
  stem:"A contract qualifies for over-time recognition using the cost-to-cost input method. Price $1,000,000; estimated total cost $800,000; cost incurred to date $200,000. Revenue recognized to date is:",
  choices:["$200,000","$250,000","$50,000","$1,000,000"], answer:1,
  explanation:"Progress = 200,000 / 800,000 = 25%. Revenue = 25% × $1,000,000 = $250,000 (gross profit to date $50,000)." },
{ id:"BARQ28", section:"BAR", area:"II", topic:"Stock compensation",
  stem:"On 1/1, a company grants 10,000 options with a grant-date fair value of $15 each, cliff-vesting after 3 years of service. Annual compensation expense is:",
  choices:["$150,000","$50,000","$15,000","$0 until exercise"], answer:1,
  explanation:"Total cost = 10,000 × $15 = $150,000, recognized straight-line over the 3-year requisite service period = $50,000/year. No remeasurement for equity-classified awards." },
{ id:"BARQ29", section:"BAR", area:"II", topic:"Contingent consideration",
  stem:"In a business combination, contingent consideration classified as a LIABILITY is:",
  choices:["Ignored until paid","Recorded at acquisition-date fair value and remeasured through earnings each period","Recorded at acquisition-date fair value and never remeasured","Charged to goodwill as it changes"], answer:1,
  explanation:"Liability-classified earnouts: fair value at acquisition (part of consideration), then remeasured through income. EQUITY-classified contingent consideration is not remeasured." },
{ id:"BARQ30", section:"BAR", area:"II", topic:"Translation vs remeasurement",
  stem:"A foreign subsidiary's functional currency is its LOCAL currency. Converting its statements to the parent's reporting currency produces:",
  choices:["Remeasurement gains/losses in net income","A translation adjustment reported in OCI (current-rate method)","No conversion effect","Gains/losses in retained earnings"], answer:1,
  explanation:"Functional = local → TRANSLATE (current-rate method; assets/liabilities at period-end rate) with the adjustment in OCI/CTA. Functional = parent's currency → REMEASURE (temporal) with gains/losses in income." },
{ id:"BARQ31", section:"BAR", area:"II", topic:"Lessor accounting",
  stem:"In a SALES-TYPE lease (collectibility probable), at commencement the lessor:",
  choices:["Keeps the asset and records straight-line income","Derecognizes the asset, records a net investment in the lease, and recognizes selling profit immediately","Defers all profit over the term","Records the asset at fair value through OCI"], answer:1,
  explanation:"Sales-type: derecognize the asset, record the net investment (lease receivable + unguaranteed residual), recognize selling profit at commencement, then interest income over the term. Direct financing defers profit into the net investment." },
{ id:"BARQ32", section:"BAR", area:"III", topic:"Fund balance classification",
  stem:"Amounts constrained by a formal action (ordinance) of the government's HIGHEST level of decision-making authority are classified in fund balance as:",
  choices:["Restricted","Committed","Assigned","Nonspendable"], answer:1,
  explanation:"Committed = self-imposed by highest authority (reversible only by the same action). Restricted = EXTERNAL constraints (grantors, creditors, law). Assigned = intent expressed by management. Nonspendable = form (inventory, prepaid)." },
{ id:"BARQ33", section:"BAR", area:"III", topic:"Property tax revenue",
  stem:"Under modified accrual, property taxes collected within ____ after year-end are typically recognized as current-year revenue:",
  choices:["6 months","60 days","One year","30 days"], answer:1,
  explanation:"'Available' for property taxes is operationalized as collected within 60 days of year-end. Later collections are deferred inflows in the funds (full revenue government-wide when levied, net of uncollectibles)." },
{ id:"BARQ34", section:"BAR", area:"III", topic:"Encumbrances",
  stem:"A general fund issues a $90,000 purchase order for equipment. At that moment it records:",
  choices:["An expenditure of $90,000","An encumbrance of $90,000","A capital asset of $90,000","Nothing until the invoice arrives"], answer:1,
  explanation:"Encumbrance accounting earmarks budget when the PO is issued. On receipt of goods: reverse the encumbrance, record the EXPENDITURE (modified accrual — no capital asset in the fund)." },

/* ============================== ISC (Areas I–III) ============================== */
{ id:"ISCQ19", section:"ISC", area:"I", topic:"SDLC",
  stem:"End users execute realistic transactions in a non-production environment to confirm the system meets business requirements before go-live. This is:",
  choices:["Unit testing","Integration testing","User acceptance testing (UAT)","Regression testing"], answer:2,
  explanation:"UAT is the business sign-off stage of the SDLC. Unit tests cover components; integration tests cover interfaces; regression confirms existing functions still work after changes." },
{ id:"ISCQ20", section:"ISC", area:"I", topic:"Processing modes",
  stem:"Which control BEST detects that a batch of transactions was processed incompletely?",
  choices:["Passwords on the application","Comparing batch control totals (record counts, hash totals) before and after processing","Annual user-access review","Database normalization"], answer:1,
  explanation:"Batch control totals (record counts, financial totals, hash totals) reconcile input to output and surface dropped or duplicated records — the classic completeness control for batch processing." },
{ id:"ISCQ21", section:"ISC", area:"I", topic:"Data architecture",
  stem:"A data warehouse differs from a data lake in that the warehouse:",
  choices:["Stores raw data in any native format","Holds structured, cleansed, schema-defined data optimized for reporting and analysis","Is always on-premises","Cannot support SQL queries"], answer:1,
  explanation:"Warehouse = curated, structured (schema-on-write), reporting-ready. Lake = raw, multi-format (schema-on-read). Governance and quality controls matter more for the lake's downstream uses." },
{ id:"ISCQ22", section:"ISC", area:"I", topic:"EDI",
  stem:"For EDI transactions exchanged automatically with trading partners, a key control is:",
  choices:["Manual rekeying of each transaction","Functional acknowledgments and audit trails confirming complete, authorized transmission","Disabling encryption to speed transmission","Quarterly batch processing only"], answer:1,
  explanation:"EDI removes human review, so controls shift to the pipeline: agreed standards/mapping, authentication of partners, functional acknowledgments, and complete logging/audit trails." },
{ id:"ISCQ23", section:"ISC", area:"I", topic:"RPA",
  stem:"A significant control risk introduced by robotic process automation (RPA) bots is:",
  choices:["Bots refuse repetitive work","Bot credentials with broad access and unmanaged changes to bot scripts","Bots cannot follow rules","RPA eliminates the audit trail by law"], answer:1,
  explanation:"Bots are users too: their credentials need least-privilege and vaulting, and their scripts need change management. Unmanaged bots = systematic, fast-replicating errors." },
{ id:"ISCQ24", section:"ISC", area:"I", topic:"Backups",
  stem:"A DIFFERENTIAL backup captures:",
  choices:["All data every time","Only changes since the last backup of ANY type","All changes since the last FULL backup","Only system files"], answer:2,
  explanation:"Differential = changes since last FULL (restore = full + latest differential). Incremental = changes since last backup of any type (restore = full + every incremental since)." },
{ id:"ISCQ25", section:"ISC", area:"II", topic:"Zero trust",
  stem:"The core principle of a zero-trust architecture is:",
  choices:["Trust all traffic inside the corporate firewall","Never trust, always verify — authenticate and authorize every request regardless of network location","Trust users after their first login forever","Eliminate all access controls"], answer:1,
  explanation:"Zero trust removes implicit trust by location: continuous verification, least privilege, micro-segmentation, and strong identity for every user, device, and request." },
{ id:"ISCQ26", section:"ISC", area:"II", topic:"MFA",
  stem:"A password plus a one-time code from a phone app combines which authentication factors?",
  choices:["Two 'something you know' factors","Something you know + something you HAVE","Something you know + something you ARE","Something you have + something you are"], answer:1,
  explanation:"Password = knowledge; the device generating/receiving the code = possession. Biometrics would add 'something you are.' Two different factor TYPES = true MFA." },
{ id:"ISCQ27", section:"ISC", area:"II", topic:"Social engineering",
  stem:"An attacker researches a specific CFO and sends a tailored email impersonating the CEO to request a wire transfer. This is:",
  choices:["Generic phishing","Spear phishing / business email compromise","Tailgating","SQL injection"], answer:1,
  explanation:"Targeted, researched impersonation = spear phishing (BEC when it's executive payment fraud). Mitigations: verification callbacks via known numbers, dual authorization for wires, training." },
{ id:"ISCQ28", section:"ISC", area:"II", topic:"Security testing",
  stem:"A penetration test differs from a vulnerability scan because a pen test:",
  choices:["Is fully automated and runs continuously","Actively attempts to EXPLOIT weaknesses to demonstrate real-world impact","Only reviews policy documents","Never requires authorization"], answer:1,
  explanation:"Scans enumerate potential weaknesses automatically; pen tests are human-driven, authorized attack simulations proving exploitability and chained impact. Both feed remediation prioritization." },
{ id:"ISCQ29", section:"ISC", area:"II", topic:"Patch management",
  stem:"An effective patch-management process requires:",
  choices:["Applying every patch immediately to production without testing","Risk-rating, testing, and timely deployment of patches through change management","Patching only after a breach","Annual patching windows only"], answer:1,
  explanation:"Patch management = inventory, risk-rate (exploitability/criticality), test, deploy through change control, verify. Emergency patches use expedited — but still documented — change procedures." },
{ id:"ISCQ30", section:"ISC", area:"II", topic:"DLP",
  stem:"Data loss prevention (DLP) tools primarily:",
  choices:["Back up data to the cloud","Monitor and block unauthorized exfiltration of sensitive data (email, uploads, USB)","Encrypt data at rest only","Detect malware signatures"], answer:1,
  explanation:"DLP classifies sensitive content and enforces policy on its movement — blocking or alerting on unauthorized email attachments, cloud uploads, or removable media." },
{ id:"ISCQ31", section:"ISC", area:"II", topic:"Encryption in transit",
  stem:"The standard mechanism protecting data in transit between a browser and a web application is:",
  choices:["Hashing the URL","TLS (HTTPS)","Full-disk encryption","RAID"], answer:1,
  explanation:"TLS encrypts the session (HTTPS). Full-disk encryption protects data AT REST; hashing protects integrity; RAID is availability/redundancy, not confidentiality." },
{ id:"ISCQ32", section:"ISC", area:"III", topic:"SOC roles",
  stem:"In a SOC 2 examination, the OPINION on the description and controls is issued by:",
  choices:["Service organization management","The service auditor (practitioner)","The user entities","The subservice organization"], answer:1,
  explanation:"Management provides the system description and a written ASSERTION; the independent service auditor examines and opines. User auditors then use the report." },
{ id:"ISCQ33", section:"ISC", area:"III", topic:"SOC report contents",
  stem:"Which element appears in a SOC 2 TYPE 2 report but NOT in a Type 1?",
  choices:["Management's assertion","The auditor's opinion","A description of tests of controls and their RESULTS over the period","The system description"], answer:2,
  explanation:"Type 2 adds the tests-of-controls detail and results over the coverage period (operating effectiveness). Both types contain the description, assertion, and opinion." },
{ id:"ISCQ34", section:"ISC", area:"III", topic:"TSC mapping",
  stem:"A service organization commits to 99.9% system uptime in its SLAs. The Trust Services category addressing this commitment is:",
  choices:["Confidentiality","Availability","Processing integrity","Privacy"], answer:1,
  explanation:"Availability = the system is available for operation and use as committed/agreed. Processing integrity covers complete/accurate/timely processing — a different promise." },

/* ============================== TCP (Areas I–IV) ============================== */
{ id:"TCPQ19", section:"TCP", area:"I", topic:"Net investment income tax",
  stem:"The 3.8% net investment income tax applies to the LESSER of net investment income or MAGI over the threshold ($200,000 single / $250,000 MFJ). Which income is SUBJECT to NIIT?",
  choices:["W-2 wages","Portfolio interest, dividends, and passive rental income","Distributions from a traditional IRA","Self-employment income from an active trade"], answer:1,
  explanation:"NIIT hits investment income: interest, dividends, capital gains, passive activity income, net rentals. Wages, SE income from active businesses, and retirement-plan distributions are excluded (though they can push MAGI over the threshold). The thresholds are statutory and NOT inflation-indexed." },
{ id:"TCPQ20", section:"TCP", area:"I", topic:"AMT credit",
  stem:"AMT paid because of DEFERRAL items (such as an ISO exercise) generates:",
  choices:["A permanent additional tax with no recovery","A minimum tax credit usable against regular tax in future years","A refundable credit in the current year","A deduction against AGI"], answer:1,
  explanation:"Deferral-item AMT creates the minimum tax credit, which carries forward and offsets regular tax when regular tax exceeds tentative minimum tax — the ISO AMT is (eventually) recoverable. Exclusion items (e.g., SALT addback) generate no credit." },
{ id:"TCPQ21", section:"TCP", area:"I", topic:"Roth conversions",
  stem:"The BEST year for a client to execute a traditional-to-Roth IRA conversion is generally a year when the client:",
  choices:["Has unusually HIGH taxable income","Has unusually LOW taxable income (e.g., a gap year or business loss year)","Is under age 50","Expects tax rates to fall permanently"], answer:1,
  explanation:"Conversion income is taxed at the marginal rate in the conversion year — fill low brackets in low-income years. No 10% penalty on conversions themselves. Future qualified Roth withdrawals are tax-free." },
{ id:"TCPQ22", section:"TCP", area:"I", topic:"Social Security taxation",
  stem:"The maximum portion of Social Security benefits includible in gross income is:",
  choices:["0% — benefits are always tax-free","50%","85%, depending on provisional income","100%"], answer:2,
  explanation:"Up to 85% of benefits are taxable as provisional income (AGI + tax-exempt interest + half of benefits) crosses the statutory thresholds. Planning lever: manage other income (e.g., Roth vs. traditional withdrawals)." },
{ id:"TCPQ23", section:"TCP", area:"I", topic:"Charitable bunching",
  stem:"A couple's itemized deductions hover just below the standard deduction each year. A common planning response is:",
  choices:["Stop giving to charity","Bunch several years of charitable gifts into one year (e.g., via a donor-advised fund) and take the standard deduction in other years","Convert gifts into loans to the charity","Claim both the standard deduction and itemized deductions"], answer:1,
  explanation:"Bunching concentrates deductions to clear the standard-deduction hurdle in alternating years; a donor-advised fund gives the immediate deduction while spreading actual grants over time." },
{ id:"TCPQ24", section:"TCP", area:"I", topic:"529 plans",
  stem:"Earnings withdrawn from a 529 plan for NONQUALIFIED expenses are subject to:",
  choices:["No tax — 529s are always tax-free","Ordinary income tax plus a 10% penalty on the earnings portion","Capital gains tax only","Gift tax to the beneficiary"], answer:1,
  explanation:"Qualified education withdrawals: tax-free. Nonqualified: the EARNINGS portion is ordinary income + 10% penalty (contributions return tax-free). Contributions are completed gifts eligible for the annual exclusion (with 5-year election)." },
{ id:"TCPQ25", section:"TCP", area:"II", topic:"DNI allocation",
  stem:"A trust has DNI of $40,000, including $4,000 of tax-exempt interest. It distributes $50,000 to its sole beneficiary. The beneficiary includes in TAXABLE income:",
  choices:["$50,000","$40,000","$36,000","$10,000"], answer:2,
  explanation:"DNI caps the inclusion at $40,000, and character passes through: $4,000 retains its tax-exempt character → $36,000 taxable. The trust's distribution deduction is likewise DNI minus tax-exempt items." },
{ id:"TCPQ26", section:"TCP", area:"II", topic:"Built-in gains tax",
  stem:"A C corporation elects S status while holding appreciated assets. If those assets are sold within the recognition period (5 years), the S corporation:",
  choices:["Recognizes no tax — S corps are never taxed","Pays a corporate-level built-in gains tax on the net recognized built-in gain","Passes the tax to the prior C-corp shareholders","Loses its S election automatically"], answer:1,
  explanation:"§1374 BIG tax: an entity-level tax (at the top corporate rate) on built-in gain recognized within 5 years of conversion — preventing a tax-free escape from C-corp double tax. Planning: wait out the period or sell low-gain assets first." },
{ id:"TCPQ27", section:"TCP", area:"II", topic:"§754 election",
  stem:"A §754 election allows a partnership to:",
  choices:["Skip filing Form 1065","Adjust the INSIDE basis of partnership assets on certain transfers of interests or distributions (under §743(b)/§734(b))","Convert ordinary income to capital gain","Elect out of partnership status"], answer:1,
  explanation:"§754 aligns inside and outside basis after a sale of an interest (743(b)) or certain distributions (734(b)) — e.g., a buyer of a partnership interest gets a basis step-up in their share of assets. Once made, it's generally permanent." },
{ id:"TCPQ28", section:"TCP", area:"II", topic:"Exempt organizations",
  stem:"Compared with a public charity, a private foundation is generally subject to:",
  choices:["No federal oversight","Excise taxes (e.g., on net investment income) and a minimum annual distribution requirement (~5%)","Higher contribution deduction limits for donors","No filing requirements"], answer:1,
  explanation:"Private foundations (typically single-source funded) face excise taxes, self-dealing prohibitions, and the ~5% minimum distribution rule, and donors get LOWER AGI deduction limits than for public charities." },
{ id:"TCPQ29", section:"TCP", area:"III", topic:"S election timing",
  stem:"For an S election to be effective for the CURRENT tax year, Form 2553 must generally be filed:",
  choices:["By the 15th day of the 3rd month of that year (or anytime in the prior year)","By December 31 of the current year","Within 30 days of incorporation","With the first Form 1120-S"], answer:0,
  explanation:"File by the 15th day of the 3rd month (March 15 for calendar-year) for current-year effect; later filings take effect the NEXT year (late-election relief may be available). All shareholders must consent." },
{ id:"TCPQ30", section:"TCP", area:"III", topic:"Reasonable compensation",
  stem:"An S-corp owner takes a $20,000 salary and $300,000 of distributions while working full-time. The primary tax risk is:",
  choices:["Loss of the QBI deduction entirely","The IRS recharacterizing distributions as WAGES, with back payroll taxes and penalties","Automatic S-election termination","Double taxation of the distributions"], answer:1,
  explanation:"Unreasonably low compensation invites recharacterization of distributions into wages (FICA + penalties). Set salary by market data for the role; document the analysis." },
{ id:"TCPQ31", section:"TCP", area:"III", topic:"Accumulated earnings tax",
  stem:"The accumulated earnings tax penalizes a C corporation that:",
  choices:["Pays dividends too frequently","Retains earnings beyond the reasonable needs of the business to avoid shareholder-level tax on dividends","Makes an S election","Operates at a loss"], answer:1,
  explanation:"The AET is a penalty tax on earnings accumulated beyond reasonably anticipated business needs (documented expansion plans, working capital needs defend against it). It's avoidable with planning — distributions or documented needs." },
{ id:"TCPQ32", section:"TCP", area:"IV", topic:"§1031 deadlines",
  stem:"In a deferred like-kind exchange, replacement property must be IDENTIFIED within ____ and ACQUIRED within ____ of transferring the relinquished property:",
  choices:["30 days; 90 days","45 days; 180 days","60 days; 365 days","90 days; 180 days"], answer:1,
  explanation:"The statutory 45-day identification and 180-day completion windows are rigid (no extensions except declared disasters); a qualified intermediary must hold the proceeds. These deadlines are stable, heavily tested numbers." },
{ id:"TCPQ33", section:"TCP", area:"IV", topic:"Wash sales",
  stem:"A client sells stock at a loss and repurchases substantially identical stock 20 days later. The loss is:",
  choices:["Fully deductible this year","Disallowed under the wash-sale rule (30 days before/after), with the disallowed loss ADDED to the basis of the replacement shares","Permanently lost","Converted to ordinary loss"], answer:1,
  explanation:"Wash-sale window = 30 days before AND after the sale. The disallowed loss isn't gone — it increases the replacement basis (and the holding period tacks). Planning: wait 31 days or buy a similar-but-not-identical security." },
{ id:"TCPQ34", section:"TCP", area:"IV", topic:"Recapture planning",
  stem:"A client wants to defer the §1245 depreciation recapture on equipment by selling on an installment basis. You advise that:",
  choices:["The installment method spreads the recapture over the payments","All §1245 recapture is recognized as ordinary income in the YEAR OF SALE regardless of payments received","Recapture converts to capital gain after 5 years","A like-kind exchange will defer it (post-2017)"], answer:1,
  explanation:"Recapture can't be deferred by installment reporting (year-1 recognition), and post-TCJA §1031 covers REAL property only — so equipment recapture generally can't be exchanged away either. Plan around the timing, don't fight it." }
]);
